/**
 * Punycode codec — a faithful from-scratch port of CPython's
 * `Lib/encodings/punycode.py` (the codec registered as `"punycode"`,
 * originally written by Martin v. Löwis), operating in STRICT error mode.
 *
 * This is deliberately NOT an RFC 3492 reference implementation: CPython's
 * codec differs from the RFC in observable ways (no overflow checks, no
 * non-minimal-encoding rejection, `.upper()`-folding of the extended part,
 * `rfind('-')` delimiter search, initial bias 72 rather than 72-with-basic
 * -string special casing, ...). Those quirks are reproduced exactly, because
 * matching `str.encode('punycode')` / `bytes.decode('punycode')` is the goal.
 *
 * Neither function deals with the "xn--" ACE prefix; that belongs to the IDNA
 * layer sitting above this one.
 *
 * Two implementation notes that matter for exactness:
 *
 *  1. Python iterates strings by CODEPOINT. JavaScript strings are UTF-16, so
 *     every place CPython says `for c in str` / `len(str)` / `str[i]` we work
 *     on an array of codepoint integers instead of a JS string. This keeps
 *     astral-plane characters (and lone surrogates) counted as a single unit,
 *     exactly as CPython counts them.
 *
 *  2. Python integers are arbitrary precision. On the decode side the
 *     accumulator `result`, the weight `w`, the running `pos` and the running
 *     `char` can all exceed 2**53 for adversarial input, and the
 *     `char > 0x10FFFF` guard must fire on the *exact* value CPython would
 *     compute. Those quantities are therefore BigInt. Everything bounded by
 *     the input length (the bias, `j`, array indices) stays a Number.
 *
 * @module punycode-codec
 */

/** Error thrown for every condition where CPython raises `UnicodeError`. */
export class PunycodeError extends Error {
  constructor(message) {
    super(message);
    this.name = 'PunycodeError';
  }
}

/** Punycode parameter set: base = 36, tmin = 1, tmax = 26. */
const BASE = 36;
const TMIN = 1;
const TMAX = 26;
/** Initial bias, damp and skew, per CPython's `generate_integers` / `adapt`. */
const INITIAL_BIAS = 72;
const DAMP = 700;
const SKEW = 38;
/** `((base - tmin) * tmax) // 2`, the `adapt` division threshold. */
const ADAPT_THRESHOLD = 455;

/** Digit alphabet: values 0..35 map to a-z then 0-9. */
const DIGITS = 'abcdefghijklmnopqrstuvwxyz0123456789';

const MAX_CODEPOINT = 0x10ffff;

/* ------------------------------------------------------------------ */
/* Small numeric helpers                                               */
/* ------------------------------------------------------------------ */

/**
 * Python's `//` on integers: floor division, not truncation. Every value we
 * feed it is non-negative in practice (so `/` would do), but matching Python's
 * rounding direction unconditionally removes a whole class of latent bugs.
 */
function floorDiv(a, b) {
  const q = a / b;
  // BigInt `/` truncates toward zero; correct when the true quotient is
  // negative and the division was not exact.
  return q * b !== a && (a < 0n) !== (b < 0n) ? q - 1n : q;
}

/**
 * `T(j, bias)` — the per-position digit threshold, clamped to [tmin, tmax].
 * Returns a Number: `j` is bounded by the input length and `bias` by the
 * magnitude of the deltas, so this never leaves the safe-integer range.
 */
function T(j, bias) {
  const res = BASE * (j + 1) - bias;
  if (res < TMIN) return TMIN;
  if (res > TMAX) return TMAX;
  return res;
}

/**
 * Bias adaptation (RFC 3492 §6.1 as CPython spells it).
 *
 * Computed in BigInt so that a huge `delta` coming out of the decoder adapts
 * to exactly the bias CPython would compute. `numchars` is an array length and
 * the returned bias is bounded by ~36 * log35(delta), both comfortably within
 * Number range for any input that can physically be supplied.
 *
 * @param {number|bigint} delta
 * @param {boolean} first  true for the first delta of the string
 * @param {number} numchars
 * @returns {number} the new bias
 */
function adapt(delta, first, numchars) {
  let d = BigInt(delta);
  d = first ? floorDiv(d, BigInt(DAMP)) : floorDiv(d, 2n);
  d += floorDiv(d, BigInt(numchars));
  let divisions = 0n;
  while (d > BigInt(ADAPT_THRESHOLD)) {
    d = floorDiv(d, BigInt(BASE - TMIN)); // base - tmin == 35
    divisions += BigInt(BASE);
  }
  return Number(divisions + floorDiv(BigInt(BASE) * d, d + BigInt(SKEW)));
}

/**
 * Decompose a JS string into codepoints. `Array.from` iterates by codepoint,
 * so surrogate pairs collapse to one astral value and lone surrogates survive
 * as themselves — which is precisely how CPython would see the same text.
 */
function toCodepoints(str) {
  return Array.from(str, (ch) => ch.codePointAt(0));
}

/** Rebuild a JS string from an array of codepoints, chunked to avoid blowing
 *  the argument limit on very long strings. */
function fromCodepoints(cps) {
  const CHUNK = 4096;
  if (cps.length <= CHUNK) return String.fromCodePoint(...cps);
  let out = '';
  for (let i = 0; i < cps.length; i += CHUNK) {
    out += String.fromCodePoint(...cps.slice(i, i + CHUNK));
  }
  return out;
}

/* ------------------------------------------------------------------ */
/* Encoding                                                            */
/* ------------------------------------------------------------------ */

/**
 * 3.1 Basic code point segregation.
 *
 * `base` keeps every codepoint < 128 in order; `extended` is the
 * deduplicated, ascending-sorted set of codepoints >= 128.
 */
function segregate(cps) {
  const base = [];
  const seen = new Set();
  for (const cp of cps) {
    if (cp < 128) base.push(cp);
    else seen.add(cp);
  }
  const extended = Array.from(seen).sort((a, b) => a - b);
  return { base, extended };
}

/** Number of codepoints in `cps` strictly below `max`. */
function selectiveLen(cps, max) {
  let res = 0;
  for (const cp of cps) {
    if (cp < max) res += 1;
  }
  return res;
}

/**
 * Next occurrence of `char` in `cps`, returned as `[index, pos]` where `pos`
 * is the position in the full text and `index` counts only codepoints up to
 * and including `char`. `[-1, -1]` signals "no more occurrences".
 */
function selectiveFind(cps, char, index, pos) {
  const l = cps.length;
  for (;;) {
    pos += 1;
    if (pos === l) return [-1, -1];
    const c = cps[pos];
    if (c === char) return [index + 1, pos];
    else if (c < char) index += 1;
  }
}

/**
 * 3.2 Insertion unsort coding — turns the text into the delta sequence that
 * replays the insertions in codepoint order.
 */
function insertionUnsort(cps, extended) {
  let oldchar = 0x80;
  const result = [];
  let oldindex = -1;
  for (const char of extended) {
    let index = -1;
    let pos = -1;
    const curlen = selectiveLen(cps, char);
    // Deltas stay bounded by (text length + 1) * 0x10FFFF, so Number is exact
    // on the encode side; only the decoder can be handed unbounded values.
    let delta = (curlen + 1) * (char - oldchar);
    for (;;) {
      [index, pos] = selectiveFind(cps, char, index, pos);
      if (index === -1) break;
      delta += index - oldindex;
      result.push(delta - 1);
      oldindex = index;
      delta = 0;
    }
    oldchar = char;
  }
  return result;
}

/** 3.3 Generalized variable-length integers (encode direction). */
function generateGeneralizedInteger(N, bias) {
  let out = '';
  let j = 0;
  for (;;) {
    const t = T(j, bias);
    if (N < t) {
      out += DIGITS[N];
      return out;
    }
    out += DIGITS[t + ((N - t) % (BASE - t))];
    N = Math.floor((N - t) / (BASE - t));
    j += 1;
  }
}

/** 3.4 Bias adaptation over the whole delta sequence. */
function generateIntegers(baselen, deltas) {
  let out = '';
  let bias = INITIAL_BIAS;
  for (let points = 0; points < deltas.length; points++) {
    const delta = deltas[points];
    out += generateGeneralizedInteger(delta, bias);
    bias = adapt(delta, points === 0, baselen + points + 1);
  }
  return out;
}

/**
 * Encode a string to punycode, WITHOUT the "xn--" prefix.
 *
 * Mirrors `str.encode('punycode')`: the ASCII part is emitted verbatim and,
 * when non-empty, separated from the extended part by a literal "-" — note
 * that a purely-ASCII input therefore always gains a trailing "-", and an
 * empty input encodes to the empty string.
 *
 * @param {string} str
 * @returns {string} ASCII punycode
 */
export function punycodeEncode(str) {
  const cps = toCodepoints(String(str));
  const { base, extended } = segregate(cps);
  const deltas = insertionUnsort(cps, extended);
  // `len(base)` in CPython is the ASCII codepoint count.
  const ext = generateIntegers(base.length, deltas);
  if (base.length > 0) return fromCodepoints(base) + '-' + ext;
  return ext;
}

/* ------------------------------------------------------------------ */
/* Decoding (strict)                                                   */
/* ------------------------------------------------------------------ */

/** Python's `repr()` of a single character, as used in UnicodeEncodeError. */
function pyCharRepr(cp) {
  const hex = (n, w) => n.toString(16).padStart(w, '0');
  if (cp < 0x100) return `'\\x${hex(cp, 2)}'`;
  if (cp < 0x10000) return `'\\u${hex(cp, 4)}'`;
  return `'\\U${hex(cp, 8)}'`;
}

/**
 * 3.3 Generalized variable-length integers (decode direction).
 *
 * `result` and `w` are BigInt: CPython uses unbounded ints here and a long
 * run of high digits genuinely overflows 2**53.
 *
 * @returns {[number, bigint]} `[newExtpos, value]`
 */
function decodeGeneralizedNumber(extended, extpos, bias) {
  let result = 0n;
  let w = 1n;
  let j = 0;
  for (;;) {
    if (extpos >= extended.length) {
      // CPython's spelling of the message, typo included.
      throw new PunycodeError('incomplete punicode string');
    }
    const code = extended.charCodeAt(extpos);
    extpos += 1;
    let digit;
    if (code >= 0x41 && code <= 0x5a) {
      digit = code - 0x41; // A-Z -> 0..25
    } else if (code >= 0x30 && code <= 0x39) {
      digit = code - 22; // 0-9 -> 26..35
    } else {
      throw new PunycodeError(
        `Invalid extended code point '${extended[extpos - 1]}'`
      );
    }
    const t = T(j, bias);
    result += BigInt(digit) * w;
    if (digit < t) return [extpos, result];
    w = w * BigInt(BASE - t);
    j += 1;
  }
}

/**
 * 3.2 Insertion sort coding — replays the deltas, inserting one codepoint per
 * delta into `base`.
 *
 * `base` is carried as an array of codepoints, not a JS string, so that
 * `len(base)` matches CPython's character count even once astral codepoints
 * (or bare surrogates) have been inserted.
 */
function insertionSort(baseCps, extended) {
  const base = baseCps.slice();
  let char = 0x80n;
  let pos = -1n;
  let bias = INITIAL_BIAS;
  let extpos = 0;

  while (extpos < extended.length) {
    const [newpos, delta] = decodeGeneralizedNumber(extended, extpos, bias);
    pos += delta + 1n;
    // `len(base) + 1` is recomputed every round: base grows by one codepoint
    // per insertion.
    const denom = BigInt(base.length + 1);
    char += floorDiv(pos, denom);
    if (char > BigInt(MAX_CODEPOINT)) {
      // Python's "%x": lowercase hex, no prefix.
      throw new PunycodeError(`Invalid character U+${char.toString(16)}`);
    }
    pos = ((pos % denom) + denom) % denom; // Python's non-negative %
    base.splice(Number(pos), 0, Number(char));
    // Note: `adapt` gets the length AFTER the insertion, and `extpos` is still
    // the pre-advance value, so `extpos === 0` marks the first delta.
    bias = adapt(delta, extpos === 0, base.length);
    extpos = newpos;
  }
  return base;
}

/**
 * Decode a punycode string (WITHOUT the "xn--" prefix) in strict mode.
 *
 * Mirrors `bytes.decode('punycode')`: the delimiter is the LAST "-" in the
 * whole string, the extended part is upper-cased before decoding (so the
 * codec is case-insensitive on its digits), and a string with no "-" at all is
 * treated as entirely extended.
 *
 * @param {string} ascii
 * @returns {string}
 */
export function punycodeDecode(ascii) {
  const text = String(ascii);

  // CPython does `text.encode("ascii")` first, which rejects non-ASCII input
  // before any punycode logic runs.
  for (const ch of text) {
    const cp = ch.codePointAt(0);
    if (cp > 0x7f) {
      throw new PunycodeError(
        `'ascii' codec can't encode character ${pyCharRepr(cp)} in position ` +
          `${text.indexOf(ch)}: ordinal not in range(128)`
      );
    }
  }

  const pos = text.lastIndexOf('-');
  let baseStr;
  let extended;
  if (pos === -1) {
    baseStr = '';
    extended = text.toUpperCase();
  } else {
    baseStr = text.slice(0, pos);
    extended = text.slice(pos + 1).toUpperCase();
  }

  return fromCodepoints(insertionSort(toCodepoints(baseStr), extended));
}

