/**
 * Self-test for /tmp/wf/punycode-codec.mjs
 *
 * Asserts the punycode codec against every vector supplied with the task
 * (all confirmed against the reference oracle and/or CPython's
 * `str.encode('punycode')`), plus round-trips, astral-plane coverage and the
 * strict-mode error surface.
 *
 * Run: node /tmp/wf/punycode-selftest.mjs
 */

import { strict as assert } from 'node:assert';
import {
  punycodeEncode,
  punycodeDecode,
  PunycodeError,
} from '/tmp/wf/punycode-codec.mjs';

let passed = 0;
let failed = 0;

function check(label, fn) {
  try {
    fn();
    passed += 1;
  } catch (err) {
    failed += 1;
    console.error(`FAIL  ${label}\n      ${err.message}`);
  }
}

function eqEncode(input, expected) {
  check(`encode ${JSON.stringify(input)} -> ${expected}`, () => {
    assert.equal(punycodeEncode(input), expected);
  });
}

function eqDecode(input, expected) {
  check(`decode ${JSON.stringify(input)} -> ${JSON.stringify(expected)}`, () => {
    assert.equal(punycodeDecode(input), expected);
  });
}

/** Both directions, from a full "xn--"-prefixed A-label. */
function vector(unicode, alabel) {
  assert.ok(alabel.startsWith('xn--'), `bad test vector: ${alabel}`);
  const puny = alabel.slice(4);
  eqEncode(unicode, puny);
  eqDecode(puny, unicode);
}

