// The delimiter is the LAST "-", so ASCII hyphens survive round-tripping.
vector('a-b-café', 'xn--a-b-caf-o0a');
eqEncode('l·l', 'll-0ea');

// The extended part is upper-cased before decoding => digits are
// case-insensitive, while the base part keeps its case verbatim.
eqDecode('caf-dma', 'café');
eqDecode('caf-DMA', 'café');
eqDecode('caf-DmA', 'café');
eqDecode('CAF-dma', 'CAFé');

// No "-" at all => the whole string is the extended part.
eqDecode('zca', 'ß');
eqDecode('ZCA', 'ß');

/* ------------------------------------------------------------------ */
/* 3. Astral plane (round-trip + oracle-checked A-labels)              */
/* ------------------------------------------------------------------ */

// CJK Extension B U+20000 and Deseret U+10400, confirmed via the oracle.
vector('\u{20000}', 'xn--c500a');
vector('\u{10400}', 'xn--ci0a');
vector('\u{20000}\u{20001}', 'xn--c500aa');
vector('\u{10400}\u{10401}', 'xn--ci0ab');

for (const s of [
  '\u{10000}',
  '\u{10FFFF}',
  '\u{100000}',
  '\u{1F600}',
  'a\u{20000}b\u{10400}c',
  '\u{1F600}\u{1F1E6}\u{1F1E7}',
  '\u{E0100}\u{E0101}',
  'ascii\u{1F600}mix',
]) {
  check(`astral round-trip ${JSON.stringify(s)}`, () => {
    assert.equal(punycodeDecode(punycodeEncode(s)), s);
  });
}

/* ------------------------------------------------------------------ */
/* 4. General round-trips                                             */
/* ------------------------------------------------------------------ */

for (const s of [
  '',
  'a',
  'abc',
  'café',
  'ß',
  'προγραμματισμός',
  'программирование',
  'рф',
  'సాంకేతికతłęь',
  'משהו',
  'עברית1',
  'l·l',
  'ア・イ',
  'テスト',
  '۰۱۲',
  'ابجد٠',
  'α͵β',
  'עברית׳',
  '箥糪',
  '中文测试',
  'àáâãäå',
  'é'.repeat(50),
  'x'.repeat(100) + 'é',
  'mixed-ASCII-and-Ünïcödé-42',
]) {
  check(`round-trip ${JSON.stringify(s)}`, () => {
    assert.equal(punycodeDecode(punycodeEncode(s)), s);
  });
}

/* ------------------------------------------------------------------ */
/* 5. Strict-mode errors (messages match CPython verbatim)             */
/* ------------------------------------------------------------------ */

function throwsWith(label, fn, message) {
  check(label, () => {
    assert.throws(fn, (err) => {
      assert.ok(
        err instanceof PunycodeError,
        `expected PunycodeError, got ${err && err.name}`
      );
      assert.ok(err instanceof Error, 'PunycodeError must subclass Error');
      assert.equal(err.message, message);
      return true;
    });
  });
}

throwsWith(
  'incomplete string',
  () => punycodeDecode('z'),
  'incomplete punicode string'
);
throwsWith(
  'incomplete string (long)',
  () => punycodeDecode('zzzzzzzzzzzz'),
  'incomplete punicode string'
);
throwsWith(
  'invalid extended code point',
  () => punycodeDecode('a!'),
  "Invalid extended code point '!'"
);
throwsWith(
  'invalid extended code point after base',
  () => punycodeDecode('abc-!x'),
  "Invalid extended code point '!'"
);
throwsWith(
  'invalid extended code point (space)',
  () => punycodeDecode('a b'),
  "Invalid extended code point ' '"
);
throwsWith(
  'codepoint above U+10FFFF',
  () => punycodeDecode('qn84w'),
  'Invalid character U+2f5fed'
);
throwsWith(
  'codepoint above U+10FFFF (bigint path)',
  () => punycodeDecode('h180hsrp'),
  'Invalid character U+1298aa'
);
throwsWith(
  'non-ascii input rejected like text.encode("ascii")',
  () => punycodeDecode('café'),
  "'ascii' codec can't encode character '\\xe9' in position 3: ordinal not in range(128)"
);
throwsWith(
  'non-ascii astral input',
  () => punycodeDecode('a\u{1F600}'),
  "'ascii' codec can't encode character '\\U0001f600' in position 1: ordinal not in range(128)"
);

/* ------------------------------------------------------------------ */
/* 6. Arbitrary-precision accumulator                                  */
/* ------------------------------------------------------------------ */

// '9' is digit 35, which never terminates a generalized integer, so a long
// run drives `result`/`w`/`char` far past 2**53. CPython reports the exact
// value; a Number-based accumulator could not.
throwsWith(
  'huge codepoint reported exactly (>2**53)',
  () => punycodeDecode('9'.repeat(24) + 'a'),
  'Invalid character U+3e3c85146e2e2b9c2df0cde23d2fad40e0ff76b4e1682083d069ee79'
);
throwsWith(
  'huge codepoint with base part',
  () => punycodeDecode('abc-' + '9'.repeat(20) + 'a'),
  'Invalid character U+1453a42f4ed5c9a783038dcaf2c909773600753a14d22677d37dd5f4'
);
throwsWith(
  'all-9 run never terminates',
  () => punycodeDecode('9'.repeat(40)),
  'incomplete punicode string'
);

/* ------------------------------------------------------------------ */

console.log(`\n${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);

