// Predict the oracle's line 1 (`idna.encode(domain)`) from punycodeEncode:
// each dot-separated label is emitted verbatim if pure ASCII, else
// "xn--" + punycodeEncode(label).
import { punycodeEncode, punycodeDecode } from '/tmp/wf/punycode-codec.mjs';

const domain = process.argv[2];
const pred = domain
  .split('.')
  .map((l) => {
    // eslint-disable-next-line no-control-regex
    if (/^[\x00-\x7f]*$/.test(l)) return l;
    return 'xn--' + punycodeEncode(l);
  })
  .join('.');
// Round-trip each A-label back through the decoder as an independent check.
const back = pred
  .split('.')
  .map((l) => (l.startsWith('xn--') ? punycodeDecode(l.slice(4)) : l))
  .join('.');
console.log(pred);
console.log(back);

